 "content": "def transform(grid):
    # Complete a diagonal-stripe pattern by extending the observed motif.
    # Infer stripe period from the known parallel diagonals and assign colors
    # by offset modulo that period.
    h, w = len(grid), len(grid[0])
    known = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                known[c-r] = grid[r][c]
    # Find the smallest period consistent with known diagonal stripes.
    offsets = sorted(known)
    period = None
    for p in range(1, h+w):
        if all(known[a] == known[b] for a in offsets for b in offsets if (a-b) % p == 0):
            period = p
            break
    if period is None:
        period = h+w
    # Fill residues where a seed color exists. In sparse cases, infer each
    # residue from observed offsets, otherwise preserve the original cell.
    residue_colors = {}
    for d, color in known.items():
        residue_colors[d % period] = color
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if (c-r) % period in residue_colors:
                out[r][c] = residue_colors[(c-r) % period]
    return out
